     1|/**
     2| * IVX Owner AI Executive Layer API (owner-only).
     3| *
     4| * One read-only endpoint that returns the full executive operations payload —
     5| * daily business briefing, strategic plan (30/90/yearly), opportunity engine,
     6| * decision engine, execution tracking, and the four-quadrant executive
     7| * scorecard (company / AI / engineering / capital).
     8| *
     9| *   GET /api/ivx/executive-layer → full executive layer.
    10| *
    11| * Owner-only. Composes existing engines (business-impact, capital command
    12| * center, autonomous-core, task orchestrator); never promises guaranteed
    13| * profit; cash runway stays honest-unknown without burn data.
    14| */
    15|import { assertIVXOwnerOnly, ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    16|import { buildExecutiveLayer } from '../services/ivx-executive-layer';
    17|
    18|export const OPTIONS = (): Response => ownerOnlyOptions();
    19|
    20|async function requireOwner(request: Request): Promise<Response | null> {
    21|  try {
    22|    const owner = await assertIVXOwnerOnly(request);
    23|    if (!owner.userId) {
    24|      return ownerOnlyJson({ ok: false, error: 'IVX owner authentication required.' }, 401);
    25|    }
    26|    return null;
    27|  } catch (error) {
    28|    const message = error instanceof Error ? error.message : 'IVX owner authentication failed.';
    29|    const status = /missing bearer/i.test(message) || /invalid or expired/i.test(message) ? 401 : 403;
    30|    return ownerOnlyJson({ ok: false, error: message }, status);
    31|  }
    32|}
    33|
    34|export async function handleExecutiveLayerRequest(request: Request): Promise<Response> {
    35|  const denied = await requireOwner(request);
    36|  if (denied) return denied;
    37|  const executive = await buildExecutiveLayer();
    38|  return ownerOnlyJson({ ok: true, executive: executive as unknown as Record<string, unknown> });
