   248|// ── 1. Daily business briefing ────────────────────────────────────────────────
   249|
   250|export function buildDailyBriefing(
   251|  impact: BusinessImpactDashboard,
   252|  command: CapitalCommandCenter,
   253|  autonomous: AutonomousDashboard,
   254|  now: number = Date.now(),
   255|): DailyBriefing {
   256|  const revenuePotential = impact.revenuePotential.estimatedOpportunityValueUsd;
   257|  const pipeline = command.capitalPipeline;
   258|
   259|  const openRiskItems: string[] = [];
   260|  if (impact.ceoBriefing.topRisk) {
   261|    openRiskItems.push(`${impact.ceoBriefing.topRisk.title}: ${impact.ceoBriefing.topRisk.detail}`);
   262|  }
   263|  for (const d of command.dealsAtRisk.slice(0, 3)) {
   264|    openRiskItems.push(`Deal at risk — ${d.name}: ${d.reason}`);
   265|  }
   266|  if (autonomous.subsystems.incidents.open > 0) {
   267|    openRiskItems.push(`${autonomous.subsystems.incidents.open} open incident(s) in the operations dashboard.`);
   268|  }
   269|  if (autonomous.buckets.failed > 0 || autonomous.buckets.blocked > 0) {
   270|    openRiskItems.push(
   271|      `${autonomous.buckets.failed} failed + ${autonomous.buckets.blocked} blocked work item(s) need attention.`,
   272|    );
   273|  }
   274|
   275|  // Product health derived from operations buckets + incidents.
   276|  const healthyWork = autonomous.buckets.verified + autonomous.buckets.completed;
   277|  const unhealthyWork = autonomous.buckets.failed + autonomous.buckets.blocked;
   278|  const openIncidents = autonomous.subsystems.incidents.open;
   279|  const productHealthLabel =
   280|    openIncidents === 0 && unhealthyWork === 0
   281|      ? 'Healthy'
   282|      : openIncidents > 0 || unhealthyWork > healthyWork
   283|        ? 'Degraded'
   284|        : 'Stable';
   285|
   286|  return {
   287|    date: new Date(now).toISOString(),
   288|    revenue: {
   289|      label: 'Revenue (pipeline potential)',
   290|      value: revenuePotential > 0 ? usd(revenuePotential) : '$0',
   291|      note:
   292|        revenuePotential > 0
   293|          ? `Potential upside across active opportunities; conservative reachable ${usd(impact.revenuePotential.capitalReachableUsd)}. Not guaranteed.`
   294|          : 'No quantified revenue in the pipeline yet — stays unknown until evidenced.',
   295|    },
   296|    crmPipeline: {
   297|      label: 'CRM pipeline',
   298|      value: `${pipeline.activeInvestors + pipeline.activeBuyers} active`,
   299|      note: `${pipeline.activeInvestors} investor(s) + ${pipeline.activeBuyers} buyer(s) active · ${pipeline.dealsInProgress} deal(s) in progress.`,
   300|    },
   301|    investorPipeline: {
   302|      label: 'Investor pipeline',
   303|      value: usd(pipeline.totalPipeline),
   304|      note: `Weighted ${usd(pipeline.weightedPipeline)} · ${usd(pipeline.capitalCommitted)} committed · ${usd(command.capitalRaisedThisMonth)} raised this month.`,
   305|    },
   306|    cashRunway: {
   307|      label: 'Cash runway',
   308|      value: 'Unknown',
   309|      note: 'Runway requires monthly burn + cash-on-hand inputs IVX does not yet track. Add expense/cash data to compute it — never estimated blindly.',
   310|    },
   311|    productHealth: {
   312|      label: 'Product health',
   313|      value: productHealthLabel,
   314|      note: `${healthyWork} verified/completed vs ${unhealthyWork} failed/blocked work item(s); ${openIncidents} open incident(s).`,
   315|    },
   316|    openRisks: {
   317|      count: openRiskItems.length,
   318|      items: openRiskItems.slice(0, 6),
   319|      note:
   320|        openRiskItems.length === 0
   321|          ? 'No open risks surfaced from incidents, deals, or operations right now.'
   322|          : 'Risks aggregated from the CEO briefing, deals at risk, and the operations dashboard.',
   323|    },
   324|  };
