   327|// ── 2. Strategic planner ────────────────────────────────────────────────────
   328|
   329|export function buildStrategicPlan(
   330|  impact: BusinessImpactDashboard,
   331|  command: CapitalCommandCenter,
   332|): StrategicPlan {
   333|  const pipeline = command.capitalPipeline;
   334|  const opps = impact.opportunitiesFound;
   335|  const raisedThisMonth = command.capitalRaisedThisMonth;
   336|  const activeRelationships = pipeline.activeInvestors + pipeline.activeBuyers;
   337|
   338|  const thirtyDay: StrategicGoal[] = [
