   341|      metric: command.bestInvestorToday
   342|        ? `Book a meeting on ${command.bestInvestorToday.dealName} (match ${command.bestInvestorToday.matchScore}/100)`
   343|        : 'Add 5 qualified capital relationships to the CRM',
   344|      rationale: command.bestInvestorToday
