   469|// ── 4. Decision engine ────────────────────────────────────────────────────────
   470|
   471|export function buildDecisionEngineView(
   472|  impact: BusinessImpactDashboard,
   473|  command: CapitalCommandCenter,
   474|  autonomous: AutonomousDashboard,
   475|): DecisionEngineView {
   476|  const decisions: ExecutiveDecision[] = [];
   477|  let rank = 1;
   478|
   479|  // Highest priority: protect against open risk.
   480|  if (impact.ceoBriefing.topRisk) {
   481|    decisions.push({
   482|      rank: rank++,
   483|      title: `Resolve: ${impact.ceoBriefing.topRisk.title}`,
   484|      action: 'Triage and clear the top risk before advancing new work.',
   485|      rationale: impact.ceoBriefing.topRisk.detail,
   486|      estimatedImpact: 'Protects reliability + in-flight value',
   487|      estimatedImpactUsd: null,
   488|      riskLevel: 'high',
   489|    });
   490|  }
   491|
   492|  // Capture the best investor today.
   493|  if (command.bestInvestorToday) {
   494|    decisions.push({
   495|      rank: rank++,
   496|      title: `Engage ${command.bestInvestorToday.name}`,
   497|      action: `Send the owner-approved intro for ${command.bestInvestorToday.dealName} and book a meeting.`,
   498|      rationale: `Highest-fit capital source (match ${command.bestInvestorToday.matchScore}/100). Evidence: ${command.bestInvestorToday.evidence.join('; ')}`,
   499|      estimatedImpact: 'Advances committed capital',
   500|      estimatedImpactUsd: command.capitalPipeline.weightedPipeline > 0 ? command.capitalPipeline.weightedPipeline : null,
   501|      riskLevel: 'medium',
   502|    });
   503|  }
   504|
   505|  // Capture the highest revenue opportunity.
   506|  const revenuePick = impact.ceoBriefing.topRevenueOpportunity ?? impact.ceoBriefing.topOpportunity;
   507|  if (revenuePick) {
   508|    const usdValue = impact.revenuePotential.estimatedOpportunityValueUsd;
   509|    decisions.push({
