   518|  }
   519|
   520|  // Clear follow-ups / meetings if backlog is forming.
   521|  const attentionCount = command.meetingsNeeded.length + command.followUpsNeeded.length;
   522|  if (attentionCount > 0) {
   523|    decisions.push({
   524|      rank: rank++,
   525|      title: 'Clear the relationship backlog',
