   567|    executed += t.completedBlockIds.length;
   568|    const left = Math.max(0, t.totalBlocks - t.completedBlockIds.length);
   569|    remaining += left;
   570|    if (t.status === 'running' || t.status === 'queued') inProgress += 1;
   571|    if (t.status === 'blocked' || t.status === 'failed') blocked += 1;
   572|  }
   573|
   574|  const recent = [...tasks]
   575|    .sort((a, b) => Date.parse(b.updatedAt ?? '') - Date.parse(a.updatedAt ?? ''))
   576|    .slice(0, 5)
   577|    .map((t) => ({
