 * "Funds Received" — everything upstream is intent, not money in the bank.
 */
export type FinancialTransactionStatus =
  | 'projected'
  | 'requested'
  | 'soft_commitment'
  | 'signed_commitment'
  | 'pending_wire'
  | 'escrow_received'
  | 'bank_received'
  | 'returned'
  | 'cancelled';

